	ld hl,YY                        ; 7F3D  2110fa
	ld a,45H                        ; 7F40  3e45
	ld c,b                          ; 7F42  48
	ld b,00H                        ; 7F43  0600
	cpir                            ; 7F45  edb1
	pop hl                          ; 7F47  e1
	jr z,L7F2B                      ; 7F48  28e1
