; ----------------------------------------------------------------------------
; Gate area (see B3b): 7F80H..7F98H JP table into this image for code that runs in the
; JAPAN ROM / B3b with port 3DH = 05H; 7F9BH..7FFCH accessors identical to B3b's: they set
; 3DH := 02H (B3b + JAPAN ROM in page 2), read from 8000H.., and switch back with 3DH := 05H.
; Because page 1 changes under the running code, both images carry the same bytes here.
; ----------------------------------------------------------------------------
L7F80:
	jp KJPAGE0                      ; 7F80  c32775
L7F83:
	jp KJPAGEFWD                    ; 7F83  c32a75
L7F86:
	jp KJPAGEBACK                   ; 7F86  c33a75
L7F89:
	jp L7307                        ; 7F89  c30773
L7F8C:
	jp KJCOLLECT                    ; 7F8C  c32373
L7F8F:
	jp L79B3                        ; 7F8F  c3b379
L7F92:
	jp KJSHOW                       ; 7F92  c36273
L7F95:
	jp L7A2A                        ; 7F95  c32a7a
L7F98:
	jp L7A36                        ; 7F98  c3367a



;------------------------------------------------------------------------------
; 7F9BH - Read the word at 8000H of the JAPAN ROM -> DE
;------------------------------------------------------------------------------
JRDW8000:
	call SET3D02                    ; 7F9B  cdf17f
	ld de,(8000H)                   ; 7F9E  ed5b0080
	jr SET3D05                      ; 7FA2  1855



;------------------------------------------------------------------------------
; 7FA4H - Copy BC bytes from the JAPAN ROM, then 7 more after a skipped byte
;------------------------------------------------------------------------------
JRCOPY:
	call SET3D02                    ; 7FA4  cdf17f
	ldir                            ; 7FA7  edb0
	inc de                          ; 7FA9  13
	ld c,07H                        ; 7FAA  0e07
	ldir                            ; 7FAC  edb0
	jr SET3D05                      ; 7FAE  1849



;------------------------------------------------------------------------------
; 7FB0H - Copy BC bytes from the ROM selected by FDF6H
;------------------------------------------------------------------------------
JRCOPYX:
	ld a,(0FDF6H)                   ; 7FB0  3af6fd
	call SET3DA                     ; 7FB3  cdf37f
	ldir                            ; 7FB6  edb0
	jr SET3D05                      ; 7FB8  183f



;------------------------------------------------------------------------------
; 7FBAH - Read the ROM word at HL -> HL
;------------------------------------------------------------------------------
JRDWHL:
