	ld a,(hl)                       ; 7FBD  7e
	inc hl                          ; 7FBE  23
	ld h,(hl)                       ; 7FBF  66
	ld l,a                          ; 7FC0  6f
	jr SET3D05                      ; 7FC1  1836



;------------------------------------------------------------------------------
; 7FC3H - Read the ROM byte and word at HL -> C, DE
;------------------------------------------------------------------------------
JRDBDW:
